import time
import threading
from enum import Enum
from collections import deque

class BreakerState(Enum):
    CLOSED = "closed"
    OPEN = "open"
    HALF_OPEN = "half_open"

class ModelAPICircuitBreaker:
    def __init__(self, failure_threshold=0.5, window_size=20,
                 cooldown_seconds=30, half_open_probes=3, fallback=None):
        self.failure_threshold = failure_threshold
        self.window_size = window_size
        self.cooldown_seconds = cooldown_seconds
        self.half_open_probes = half_open_probes
        self.fallback = fallback or (lambda *a, **k: {"degraded": True})
        self._outcomes = deque(maxlen=window_size)
        self._state = BreakerState.CLOSED
        self._opened_at = None
        self._half_open_successes = 0
        self._half_open_attempts = 0
        self._lock = threading.Lock()

    def _failure_rate(self):
        if not self._outcomes:
            return 0.0
        return sum(1 for ok in self._outcomes if not ok) / len(self._outcomes)

    def _record(self, success):
        self._outcomes.append(success)

    def call(self, fn, *args, **kwargs):
        with self._lock:
            now = time.time()
            if self._state == BreakerState.OPEN:
                if now - self._opened_at >= self.cooldown_seconds:
                    self._state = BreakerState.HALF_OPEN
                    self._half_open_successes = 0
                    self._half_open_attempts = 0
                else:
                    return self.fallback(*args, **kwargs)

        try:
            result = fn(*args, **kwargs)
        except Exception:
            with self._lock:
                self._record(False)
                if self._state == BreakerState.HALF_OPEN:
                    self._half_open_attempts += 1
                    self._state = BreakerState.OPEN
                    self._opened_at = time.time()
                elif self._failure_rate() >= self.failure_threshold and len(self._outcomes) >= 5:
                    self._state = BreakerState.OPEN
                    self._opened_at = time.time()
            return self.fallback(*args, **kwargs)

        with self._lock:
            self._record(True)
            if self._state == BreakerState.HALF_OPEN:
                self._half_open_attempts += 1
                self._half_open_successes += 1
                if self._half_open_attempts >= self.half_open_probes:
                    if self._half_open_successes == self._half_open_attempts:
                        self._state = BreakerState.CLOSED
                        self._outcomes.clear()
                    else:
                        self._state = BreakerState.OPEN
                        self._opened_at = time.time()
        return result

