from dataclasses import dataclass, field

@dataclass
class CostEvent:
    event_id: str
    tenant: str
    feature: str
    model: str
    input_tokens: int
    output_tokens: int
    timestamp: float
    cost_usd: float

class AttributionError(Exception):
    pass

PRICING = {
    "gpt-x-large": {"input": 0.005, "output": 0.015},
    "gpt-x-small": {"input": 0.0003, "output": 0.0006},
}

class CostAttributionMiddleware:
    def __init__(self):
        self._events = []
        self._lock = threading.Lock()

    def wrap_call(self, model_fn, *, tenant, feature, model, prompt, **kwargs):
        if not tenant or not feature:
            raise AttributionError(
                f"Call to model={model} missing tenant/feature attribution; refusing to log unattributed usage"
            )
        response = model_fn(prompt=prompt, model=model, **kwargs)
        input_tokens = response["usage"]["input_tokens"]
        output_tokens = response["usage"]["output_tokens"]
        rate = PRICING.get(model)
        if rate is None:
            raise AttributionError(f"Unknown model '{model}' has no pricing entry; refusing to log unpriced usage")
        cost = (input_tokens / 1000.0) * rate["input"] + (output_tokens / 1000.0) * rate["output"]
        event = CostEvent(
            event_id=str(uuid.uuid4()), tenant=tenant, feature=feature, model=model,
            input_tokens=input_tokens, output_tokens=output_tokens,
            timestamp=time.time(), cost_usd=cost,
        )
        threading.Thread(target=self._record, args=(event,), daemon=True).start()
        return response

    def _record(self, event):
        with self._lock:
            self._events.append(event)

    def aggregate(self, tenant=None, feature=None, start=None, end=None):
        with self._lock:
            rows = list(self._events)
        total = 0.0
        for e in rows:
            if tenant and e.tenant != tenant:
                continue
            if feature and e.feature != feature:
                continue
            if start and e.timestamp < start:
                continue
            if end and e.timestamp > end:
                continue
            total += e.cost_usd
        return round(total, 4)

import re

BLOCK_PATTERNS = [
    re.compile(r"ignore (all|previous) instructions", re.I),
    re.compile(r"\b(?:credit[- ]?card|ssn)\s*[:#]?\s*\d", re.I),
]
ALLOW_PATTERNS = [
    re.compile(r"^(hi|hello|hey)\b", re.I),
]

class GuardrailDecision:
    def __init__(self, allowed, stage, reason):
        self.allowed = allowed
        self.stage = stage
        self.reason = reason

def regex_stage(text):
    for p in BLOCK_PATTERNS:
        if p.search(text):
            return GuardrailDecision(False, "regex", f"matched block pattern: {p.pattern}")
    for p in ALLOW_PATTERNS:
        if p.search(text):
            return GuardrailDecision(True, "regex", "matched known-safe greeting pattern")
    return None  # unresolved, escalate

def classifier_stage(text, classifier_fn, unsafe_threshold=0.85, safe_threshold=0.15):
    score = classifier_fn(text)  # returns probability of policy violation, 0.0-1.0
    if score >= unsafe_threshold:
        return GuardrailDecision(False, "classifier", f"unsafe score {score:.2f} >= {unsafe_threshold}")
    if score <= safe_threshold:
        return GuardrailDecision(True, "classifier", f"safe score {score:.2f} <= {safe_threshold}")
    return None  # ambiguous band, escalate

def policy_model_stage(text, policy_model_fn):
    verdict = policy_model_fn(text)  # slow, careful reasoning call
    return GuardrailDecision(verdict["allowed"], "policy_model", verdict["reason"])

def run_guardrail_pipeline(text, classifier_fn, policy_model_fn):
    decision = regex_stage(text)
    if decision is not None:
        return decision
    decision = classifier_stage(text, classifier_fn)
    if decision is not None:
        return decision
    return policy_model_stage(text, policy_model_fn)

